<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Program,Department};use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Support\Facades\Storage;
class ProgramController extends Controller{public function index(){return view('admin.catalog.index',['title'=>'Программы','route'=>'programs','items'=>Program::with('department')->orderBy('sort')->get()]);}public function create(){return $this->form(new Program);}public function store(Request $r){Program::create($this->data($r));return redirect()->route('admin.programs.index')->with('ok','Программа создана');}public function edit(Program $program){return $this->form($program);}public function update(Request $r,Program $program){$old=$program->document;$d=$this->data($r,$program);$program->update($d);if(isset($d['document'])&&$old&&$old!==$d['document'])Storage::disk('public')->delete($old);return redirect()->route('admin.programs.index')->with('ok','Сохранено');}public function destroy(Program $program){if($program->document)Storage::disk('public')->delete($program->document);$program->delete();return back();}private function form($item){return view('admin.catalog.program',['item'=>$item,'departments'=>Department::orderBy('sort')->get()]);}private function data(Request $r,?Program $item=null){$d=$r->validate(['department_id'=>'nullable|exists:departments,id','name'=>'required|max:255','description'=>'nullable|max:2000','content'=>'nullable','duration'=>'nullable|max:100','age'=>'nullable|max:100','admission_requirements'=>'nullable|max:1000','tuition'=>'nullable|max:255','document'=>'nullable|file|max:20480|mimes:pdf,doc,docx','sort'=>'nullable|integer']);$base=Str::slug($r->input('slug')?:$d['name'])?:'program';$slug=$base;$i=2;while(Program::where('slug',$slug)->when($item,fn($q)=>$q->where('id','!=',$item->id))->exists())$slug=$base.'-'.$i++;$d['slug']=$slug;if($r->hasFile('document'))$d['document']=$r->file('document')->store('programs','public');$d['is_active']=$r->boolean('is_active');return $d;}}